/**
 * pixdcon 2: composition root. The only place where modules meet.
 *
 * Every module gets what it needs through its constructor; no module imports
 * another module's instance or another worker's file. What crosses worker
 * boundaries crosses here: instances, and the functions listed in
 * `Factories` (types.js). Phase-3 workers fill their modules behind the
 * interfaces and do not edit this file: a start step whose module is still a
 * skeleton is skipped (core/todo.js runStep) and lights up once it is built.
 * Owner: core/state worker.
 *
 * BUILD ORDER (createApp, async). What must be known before what:
 *   1. version record                 fail closed, one clear line (A-001)
 *   2. clock, logger, epoch
 *   3. config store, and load()       before anything below exists. Never fatal:
 *                                     an invalid file leaves the UI reachable (A-007)
 *   4. MQTT namespace                 `mqtt` block of the loaded config → topics → last will → gateway.
 *                                     The will is part of the CONNECT packet and every module holds
 *                                     topic strings, so the namespace is fixed for this run. A later
 *                                     change of `mqtt.*` is reported as restartRequired and applies at
 *                                     the next start. An invalid config.json at start means the
 *                                     namespace is not known: MQTT then stays off for this run, so a
 *                                     broken file can never make v2 publish under v1's topics.
 *   5. v1 ownership feed              reads v1's device list during the switch-over
 *   6. overlay service, runtime config   the effective config and the one output policy.
 *                                     Who writes the blob overlay is decided here too, once
 *                                     for the run (blobWriter below)
 *   7. scenes, settings, state, health, rendering, status, API
 *
 * START ORDER (v1's order with its faults removed, matrix A-006 to A-020):
 *   1. HTTP server                    first, so no display can delay the UI (A-019)
 *   2. MQTT connect, at most 5 s      optional (A-009, A-011)
 *   3. v1 ownership, overlay service  read the retained layer up to the settle hint, no fixed sleep (A-013)
 *   4. runtime config                 effective devices and scenes, outputs resolved; the overlay
 *                                     service is told who is driven (applyOutputs)
 *   5. scene registry, settings       schemas are known before setting overlays are judged for good (A-018).
 *                                     The registry's work runs in one lane (below) and is finished
 *                                     before anything that reads scenes starts
 *   6. state store                    desired state per device, sources resolved
 *   7. health, scheduler              all devices concurrently; mode and brightness known before the first frame
 *   8. status publisher, live channel wiring, controller health ticker
 *   9. config and scene watchers      last, with the running config as their baseline (A-BUG-35)
 *
 * Shutdown (A-034 to A-037): stop inputs (watchers, HTTP), close the
 * registry lane and wait for it (bounded), stop the scheduler (bounded),
 * release scenes, publish "offline", disconnect MQTT. The whole sequence is
 * limited to 8 s to fit Docker's 10 s grace period.
 *
 * ORDER OF ASYNCHRONOUS WORK (core/ordering.js). Whatever reads scene files
 * takes time and can be asked for again before it has finished: the first
 * load, a change of the effective scene map (config.json, blob scenes, a
 * path overlay), a changed scene file. All of it runs in one lane, one piece
 * at a time, in the order it was asked for, so an earlier and slower import
 * can never finish after a later one and put its result on top. The lane is
 * drained before the settings service, the state store and the scheduler
 * start. The scene registry and the scene runtime are called from the lane
 * only.
 *
 * At shutdown the lane is closed. That skips what has not started and
 * aborts the lane's signal; it cannot stop an import that is running. So
 * the signal is the fence, and the wait is not: every piece of scene work
 * hands the signal to the registry call it awaits (the registry commits
 * nothing once it is aborted, scene-registry.js) and asks it again before
 * its next step (createLane's runThen is that shape as one call). Shutdown
 * then waits for the running piece, at most 2 s,
 * and goes on to release the scenes. An import that comes back later, after
 * the wait ran out and even after stop() returned, finds the signal aborted:
 * it commits nothing and invalidates nothing.
 *
 * Environment:
 *   PIXDCON_CONFIG_PATH       config.json; its directory is the data directory (image default /data/config.json)
 *   WEB_PORT                  default 8080
 *   LOG_LEVEL                 error | warn | info | debug
 *   MOSQUITTO_HOST, MQTT_PORT, MOSQUITTO_USER, MOSQUITTO_PASS     broker, v1 names; no MOSQUITTO_PASS = no MQTT
 *   PIXDCON2_MQTT_ANONYMOUS   1 = connect without credentials (dev and tests, in-memory broker)
 *   PIXDCON2_INSTANCE         default "pixdcon2"; the edge lane uses "pixdcon2-edge"
 *   PIXDCON2_DEFAULT_OUTPUT   drive | shadow for devices that do not say and a config without output.default (default drive)
 *   PIXDCON2_FORCE_SHADOW     1 = no device of this instance is ever driven, whatever config.json says
 *   PIXDCON2_SHARED_ROOT      where scenes/, lib/, assets/ and version.json are (found automatically)
 *   TZ, SONNEN_BATTERY_HOST, SONNEN_BATTERY_API_TOKEN, SYNCBOX_BEARER_TOKEN    read by scenes, not by v2 (A-174, A-175)
 */

import { randomBytes } from "node:crypto";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { isDeepStrictEqual } from "node:util";
import { HttpServer } from "./api/http-server.js";
import { LiveChannel, wireLiveChannel } from "./api/live-channel.js";
import { registerV1Routes } from "./api/routes-v1.js";
import { registerV2Routes } from "./api/routes-v2.js";
import { ConfigStore } from "./config/config-store.js";
import { DEFAULTS, changeImpact } from "./config/schema.js";
import { systemClock } from "./core/clock.js";
import { createLogger } from "./core/logger.js";
import { createLane } from "./core/ordering.js";
import { NotImplementedError, runStep } from "./core/todo.js";
import { rasterizeAwtrixApp } from "./drivers/awtrix-raster.js";
import { BUILTIN_MODES, findBuiltin } from "./drivers/builtin-modes.js";
import { createDriver, sizeOf } from "./drivers/driver.js";
import { HealthModel } from "./health/health-model.js";
import { TelemetryCollector } from "./health/telemetry.js";
import { pixooDiscovery, ulanziDiscovery } from "./mqtt/ha-discovery.js";
import { MqttGateway, offlineSceneContext } from "./mqtt/mqtt-gateway.js";
import { StatusPublisher } from "./mqtt/status-publisher.js";
import { createTopics } from "./mqtt/topics.js";
import { OverlayService } from "./overlay/overlay-service.js";
import { PreviewStore } from "./render/preview-store.js";
import { Scheduler } from "./render/scheduler.js";
import { SceneRegistry } from "./scenes/scene-registry.js";
import { SceneRuntime } from "./scenes/scene-runtime.js";
import { ScenesWatcher } from "./scenes/scenes-watcher.js";
import { SettingsService } from "./scenes/settings-service.js";
import {
  createPixooSurface,
  createUlanziSurface,
} from "./scenes/v1-device-facade.js";
import {
  V2_ROOT,
  installSharedResolution,
  loadV1Font,
  readVersion,
} from "./scenes/v1-shared.js";
import {
  normalizeSettingValue,
  resolveBlobWriter,
} from "./state/precedence.js";
import { RuntimeConfig } from "./state/runtime-config.js";
import { StateStore } from "./state/state-store.js";
import { V1Ownership } from "./state/v1-ownership.js";

const SHUTDOWN_LIMIT_MS = 8000;
/** How long shutdown waits for a scene import that is running; inside the 8 s. */
const REGISTRY_DRAIN_LIMIT_MS = 2000;
const CONTROLLER_TICK_MS = 1000;

/** @type {import("./types.js").MqttStatus} */
const MQTT_DISABLED = Object.freeze({
  state: "disabled",
  url: null,
  since: null,
  connection: 0,
  lastError: null,
  settled: false,
});

/**
 * Value of a module that may still be a skeleton. Only "not built yet" falls
 * back; any other error is a real one and is thrown.
 *
 * @template T
 * @param {() => T} read
 * @param {T} fallback
 * @returns {T}
 */
function orSkeleton(read, fallback) {
  try {
    return read();
  } catch (error) {
    if (error instanceof NotImplementedError) return fallback;
    throw error;
  }
}

/**
 * @param {NodeJS.ProcessEnv} env
 * @returns {number}
 */
function readPort(env) {
  const raw = env.WEB_PORT ?? "8080";
  const port = Number(raw);
  if (!/^\d+$/.test(raw) || port > 65535) {
    throw new Error(
      `Invalid WEB_PORT "${raw}": expected a number from 0 to 65535`,
    );
  }
  return port;
}

/**
 * Build the application without starting it. Async, because config.json is
 * loaded here: the MQTT namespace comes from it and has to be known before
 * the topics, the last will and the gateway are built. Tests pass their own
 * clock, logger and environment.
 *
 * @param {NodeJS.ProcessEnv} [env]
 * @param {{clock?: import("./types.js").Clock, logger?: ReturnType<typeof createLogger>, epoch?: string}} [overrides]
 */
export async function createApp(env = process.env, overrides = {}) {
  const version = readVersion();
  const clock = overrides.clock ?? systemClock();
  const logger =
    overrides.logger ?? createLogger({ level: env.LOG_LEVEL, now: clock.now });
  const instance = env.PIXDCON2_INSTANCE || "pixdcon2";
  /** @type {import("./types.js").Epoch} */
  const epoch = overrides.epoch ?? randomBytes(4).toString("hex");
  const forceShadow = env.PIXDCON2_FORCE_SHADOW === "1";
  /** @type {import("./types.js").OutputMode} */
  const envDefaultOutput =
    env.PIXDCON2_DEFAULT_OUTPUT === "shadow" ? "shadow" : "drive";
  const port = readPort(env);
  const configPath = resolve(
    env.PIXDCON_CONFIG_PATH || resolve(V2_ROOT, "config.json"),
  );
  const dataDir = dirname(configPath);
  const startedAt = clock.now();

  installSharedResolution({ extraDirs: [dataDir] });

  // --- 3. saved state: loaded before anything is built from its content ----
  const config = new ConfigStore({ path: configPath, logger, clock });
  const configBuilt = await runStep("config.load", () => config.load(), logger);

  // --- 4. the MQTT namespace, read once ------------------------------------
  // The namespace is the `mqtt` block of a valid config.json and nothing
  // else. Defaults are never used to talk to a broker: while the config store
  // is a skeleton, and when config.json is not valid at start, MQTT stays off
  // for this run. (The topic strings below are still built, from the
  // defaults, because the route tables and the Health page name them.)
  const namespaceKnown = configBuilt && config.file().valid;
  /** @type {import("./types.js").MqttConfig} */
  const mqttConfig = Object.freeze({
    ...(configBuilt ? config.get().mqtt : DEFAULTS.mqtt),
  });
  const topics = createTopics(mqttConfig);
  // The broker publishes a CONNECT will without consulting outputOf. A
  // forced-shadow instance sharing v1's namespace must register none.
  const will =
    !forceShadow || topics.statusBase !== topics.base
      ? StatusPublisher.lastWill(topics)
      : undefined;
  const mqtt = namespaceKnown
    ? orSkeleton(
        () =>
          MqttGateway.fromEnv(env, {
            instance,
            will,
            syncTopic: topics.sync,
            logger,
            clock,
          }),
        null,
      )
    : null;

  // --- 5. and 6. who drives what, and the config as it runs ----------------
  const ownership = new V1Ownership({ mqtt, topics, clock, logger });

  /**
   * The one output policy, as a function. Before the runtime config is
   * started, and while it is a skeleton, the answer is "shadow": nothing may
   * act outward on a guess.
   *
   * @param {string|null} device null: the instance as a whole
   * @returns {import("./types.js").OutputMode}
   */
  const outputOf = (device) =>
    orSkeleton(() => runtime.outputOf(device), "shadow");

  /**
   * The blob overlay is one document for all displays, and it has one
   * writer: the instance that owns the controller topics under the base
   * topic (overlay-service.js W1; the decision is precedence.js
   * resolveBlobWriter). While the transition is on that is pixdcon v1,
   * which publishes them there and rewrites the blob itself; this instance
   * then never publishes to the blob topic. An instance that is forced
   * into shadow never writes it either (the edge lane). Every input is
   * fixed for the run: the namespace is read once, and the switch comes
   * from the environment. So the right to write the blob cannot be gained
   * while the process runs.
   */
  const blobWriter = Object.freeze(
    resolveBlobWriter({
      mqtt: mqtt !== null,
      forceShadow,
      transition: topics.transition,
    }),
  );

  /** @type {OverlayService} */
  const overlays = new OverlayService({
    mqtt,
    topics,
    outputOf,
    blobWriter: blobWriter.writer,
    schemaOf: (scene) =>
      orSkeleton(() => scenes.get(scene)?.settingsSchema ?? null, null),
    savedSuppressions: () =>
      orSkeleton(
        () =>
          config.get().devices.flatMap((device) =>
            /** @type {const} */ (["granular", "blob"]).flatMap((layer) => {
              const suppression = device.supersedes?.[layer];
              return suppression
                ? [{ device: device.name, layer, suppression }]
                : [];
            }),
          ),
        [],
      ),
    clock,
    logger,
  });
  /** @type {RuntimeConfig} */
  const runtime = new RuntimeConfig({
    config,
    overlays,
    ownership,
    mqtt: mqttConfig,
    forceShadow,
    envDefaultOutput,
    clock,
    logger,
  });

  // --- factories: what one worker's module needs from another's ------------
  /** @type {ReturnType<typeof loadV1Font>|null} */
  let font = null;
  /** @type {import("./types.js").Factories} */
  const factories = Object.freeze({
    createDriver,
    sizeOf,
    findBuiltin,
    builtinModes: BUILTIN_MODES,
    createSurface: async (device, sink) =>
      device.type === "pixoo"
        ? createPixooSurface(device, sink, await (font ??= loadV1Font()))
        : createUlanziSurface(device, sink),
    rasterizeAwtrixApp,
    discovery: Object.freeze({
      ulanzi: ulanziDiscovery,
      pixoo: pixooDiscovery,
    }),
    changeImpact,
    normalizeSettingValue,
  });

  // --- 7. scenes -----------------------------------------------------------
  /** @type {SceneRegistry} */
  const scenes = new SceneRegistry({
    baseDir: () => dataDir,
    scenes: () => orSkeleton(() => runtime.scenes(), {}),
    findBuiltin: factories.findBuiltin,
    normalizeSettingValue: factories.normalizeSettingValue,
    logger,
  });
  const settings = new SettingsService({
    config,
    runtime,
    overlays,
    registry: scenes,
    epoch,
    clock,
    logger,
  });
  const sceneRuntime = new SceneRuntime({
    registry: scenes,
    settings,
    mqttContext: mqtt
      ? (ref) => mqtt.sceneContext(ref)
      : (ref) => offlineSceneContext(ref, logger),
    settingsTopic: topics.settingsRoot,
    outputOf,
    dataDir,
    logger,
  });

  // --- state, health, rendering --------------------------------------------
  const state = new StateStore({
    config,
    runtime,
    overlays,
    scenes,
    sizeOf: factories.sizeOf,
    epoch,
    clock,
    logger,
  });
  const health = new HealthModel({
    config: () => orSkeleton(() => runtime.get().health, DEFAULTS.health),
    clock,
    logger,
  });
  const previews = new PreviewStore({ clock, logger });
  const telemetry = mqtt
    ? new TelemetryCollector({
        mqtt,
        topics,
        health,
        intervalMs: () =>
          orSkeleton(
            () => runtime.get().telemetryIntervalMs,
            DEFAULTS.telemetryIntervalMs,
          ),
        haDiscovery: mqttConfig.haDiscovery,
        discovery: factories.discovery,
        clock,
        logger,
      })
    : null;
  const scheduler = new Scheduler({
    state,
    runtime,
    factories,
    scenes: sceneRuntime,
    previews,
    health,
    telemetry,
    mqtt,
    clock,
    logger,
  });
  const statusPublisher = mqtt
    ? new StatusPublisher({
        mqtt,
        topics,
        state,
        runtime,
        config,
        clock,
        logger,
      })
    : null;
  // --- the registry lane: scene work one piece at a time, in order ---------
  const registryLane = createLane({
    onError: (name, error) => {
      if (!(error instanceof NotImplementedError))
        logger.error(`[pixdcon2] Scene registry work failed: ${name}`, error);
    },
  });
  const scenesWatcher = new ScenesWatcher({
    dirs: () =>
      orSkeleton(
        () => [
          ...new Set(
            scenes.list().map((meta) => dirname(scenes.fileOf(meta.key) ?? "")),
          ),
        ],
        [],
      ),
    onChange: async (file) => {
      await registryLane.runThen(
        `scene file changed: ${file}`,
        async (signal) => {
          // Read in the lane: the keys of a file are those of the registry
          // as it is when this piece runs, after everything queued before it.
          const keys = scenes.keysOfFile(file);
          await scenes.refresh(keys, { signal });
          return keys;
        },
        // Not reached when the lane was closed while the import ran: then
        // the registry committed nothing, and no instance is touched.
        (keys) => sceneRuntime.invalidate(keys),
      );
    },
    logger,
  });

  // --- controller status: measured, and what needs a restart ---------------
  const mqttNamespace = Object.freeze({
    baseTopic: topics.base,
    statusBaseTopic: topics.statusBase,
    settingsBaseTopic: topics.settingsBase,
    discoveryPrefix: topics.discoveryPrefix,
    transition: topics.transition,
  });
  /** @type {import("./types.js").ControllerStatus["restartRequired"]} */
  let restartRequired = null;

  /**
   * The namespace of this run is `mqttConfig`. When config.json now asks for
   * another one, or became valid after an invalid start, say so; nothing
   * moves on the wire until the restart.
   */
  const checkRestartRequired = () => {
    if (!configBuilt) return;
    /** @type {string|null} */
    let reason = null;
    if (!namespaceKnown) {
      if (config.file().valid)
        reason =
          "config.json was not valid when pixdcon started, so MQTT stayed off; restart pixdcon to connect";
    } else if (!isDeepStrictEqual({ ...config.get().mqtt }, mqttConfig)) {
      reason =
        "the MQTT settings in config.json changed; they are read at start, restart pixdcon to apply them";
    }
    if (reason === null) restartRequired = null;
    else if (restartRequired?.reason !== reason)
      restartRequired = {
        reason,
        since: new Date(clock.now()).toISOString(),
      };
  };

  /** @returns {import("./types.js").MqttStatus} */
  const mqttStatus = () =>
    mqtt ? orSkeleton(() => mqtt.status(), MQTT_DISABLED) : MQTT_DISABLED;

  /** @returns {import("./types.js").ControllerStatus} */
  const controller = () => {
    // Measured as soon as the scheduler and the health model are built. A
    // skeleton is said to be one (`measured: false`) instead of claiming ok.
    const measured = orSkeleton(() => {
      const supervision = scheduler.status();
      return health.controller({
        watchdogAt: supervision.lastWatchdogAt,
        watchdogIntervalMs: supervision.watchdogIntervalMs,
        mqtt: mqttStatus(),
        configValid: config.file().valid,
        restartRequired: restartRequired !== null,
      });
    }, null);
    return {
      instance,
      epoch,
      version: version.version,
      version_scheme: version.version_scheme,
      startedAt: new Date(startedAt).toISOString(),
      status: measured?.status ?? "ok",
      reasons: measured?.reasons ?? [],
      measured: measured !== null,
      forceShadow,
      blobWriter,
      mqttNamespace,
      restartRequired,
    };
  };

  // --- API -------------------------------------------------------------------
  /** @type {LiveChannel} */
  const live = new LiveChannel({
    epoch,
    snapshot: () => ({
      controller: controller(),
      mqtt: mqttStatus(),
      config: config.file(),
      devices: state.views(),
      incarnations: runtime.incarnations(),
      scenes: scenes.list(),
      builtins: {
        ulanzi: [...factories.builtinModes.ulanzi],
        pixoo: [...factories.builtinModes.pixoo],
      },
      overlays: overlays.list(),
    }),
    onSession: (session, connected) =>
      settings.sessionConnection(session, connected),
    clock,
    logger,
  });
  const server = new HttpServer({
    port,
    webRoot: resolve(V2_ROOT, "web"),
    logger,
    // Where an answer stands in the order of this run (types.js
    // ServerPosition). While the live channel is a skeleton nothing has been
    // published: seq 0.
    position: () => `${epoch}-${orSkeleton(() => live.seq(), 0)}`,
  });
  /** @type {import("./api/routes-v1.js").ApiDeps} */
  const apiDeps = {
    epoch,
    config,
    runtime,
    ownership,
    state,
    overlays,
    scenes,
    settings,
    previews,
    scheduler,
    health,
    telemetry,
    mqtt,
    live,
    builtinModes: factories.builtinModes,
    logger,
    clock,
    controller,
  };
  // The Docker HEALTHCHECK reads this route: 200 for ok and degraded, 503
  // when the supervision itself failed (matrix A-161).
  server.route(
    "GET",
    "/api/health",
    () => {
      const status = controller();
      return {
        status: status.status === "failed" ? 503 : 200,
        body: {
          ...status,
          uptimeSeconds: Math.floor((clock.now() - startedAt) / 1000),
        },
      };
    },
    {
      summary:
        "Controller health for the Docker HEALTHCHECK: 200 ok or degraded, 503 failed",
      ok: "ControllerStatus & {uptimeSeconds}",
      rows: "A-161",
    },
  );
  registerV1Routes(server, apiDeps);
  registerV2Routes(server, apiDeps);

  let stopping = false;
  /** @type {() => void} */
  let unwireLive = () => {};
  /** @type {{cancel: () => void}|null} */
  let controllerTicker = null;
  let lastControllerKey = "";

  /** Tell the pages when the measured controller status changed. */
  const publishControllerIfChanged = () => {
    checkRestartRequired();
    const status = controller();
    const key = JSON.stringify([
      status.status,
      status.reasons,
      status.restartRequired,
      status.measured,
    ]);
    if (key === lastControllerKey) return;
    const first = lastControllerKey === "";
    lastControllerKey = key;
    if (!first) orSkeleton(() => live.publish("controller", status), 0);
  };

  /**
   * Who is driven, for the two scene layers of the overlay service. Until
   * the first call they hold every device in shadow.
   *
   * @param {import("./types.js").EffectiveConfig} effective
   */
  const tellOutputs = (effective) =>
    orSkeleton(
      () =>
        overlays.applyOutputs(
          effective.devices.map((device) => ({
            name: device.name,
            output: device.output.mode,
          })),
        ),
      undefined,
    );

  /**
   * The effective scene map changed (config.json, blob scenes or a granular
   * path overlay): the registry follows, and the instances of the scenes it
   * names are replaced. Queued in the registry lane: a change that arrives
   * while the first load or an earlier change is still importing waits for
   * it, and is applied after it.
   *
   * The overlay service is told the resolved output of every device with
   * the same event, and once after the runtime config was started: that is
   * how the scene layers learn who is driven, and who left
   * (OverlayService.applyOutputs).
   *
   * @param {{effective: import("./types.js").EffectiveConfig, diff: import("./types.js").EffectiveDiff}} change
   */
  const onRuntimeChanged = ({ effective, diff }) => {
    tellOutputs(effective);
    if (
      diff.scenesAdded.length + diff.scenesRemoved.length === 0 &&
      diff.scenesChanged.length === 0
    )
      return;
    void registryLane.runThen(
      "scene map changed",
      (signal) =>
        scenes.sync(
          {
            added: diff.scenesAdded,
            removed: diff.scenesRemoved,
            changed: diff.scenesChanged,
          },
          { signal },
        ),
      // As above: after the close nothing is committed and nothing follows.
      ({ keys }) => sceneRuntime.invalidate(keys),
    );
  };

  return {
    instance,
    epoch,
    logger,
    server,
    topics,
    factories,
    controller,
    modules: {
      config,
      mqtt,
      ownership,
      overlays,
      runtime,
      scenes,
      settings,
      sceneRuntime,
      state,
      health,
      previews,
      scheduler,
      live,
      registryLane,
    },

    /** @returns {Promise<{port: number}>} */
    async start() {
      logger.info(
        `[pixdcon2] Starting ${instance} ${version.version} (${version.version_scheme})`,
      );
      if (forceShadow)
        logger.warn(
          "[pixdcon2] PIXDCON2_FORCE_SHADOW is set: no display is driven by this instance",
        );
      if (!configBuilt)
        logger.debug(
          "[pixdcon2] skeleton: the config store is not built, so MQTT stays off",
        );
      else if (!namespaceKnown)
        logger.warn(
          "[pixdcon2] config.json is not valid, so the MQTT topics of this instance are not known: MQTT stays off in this run. Repair the file, then restart.",
        );
      else if (topics.transition)
        logger.info(
          `[pixdcon2] Transition: controller topics under ${topics.statusBase}, v1's device list is read from ${topics.v1ConfigEffective}; ${topics.overlayBlob} is written by pixdcon v1 only`,
        );
      const { port: listening } = await server.start();
      await runStep("mqtt.start", () => mqtt?.start(), logger);
      await runStep("ownership.start", () => ownership.start(), logger);
      await runStep("overlays.start", () => overlays.start(), logger);
      runtime.on("changed", onRuntimeChanged);
      await runStep("runtime.start", () => runtime.start(), logger);
      // The first effective config: from here on the scene layers know who
      // is driven. A later change arrives through onRuntimeChanged.
      await runStep(
        "overlays.outputs",
        () => tellOutputs(runtime.get()),
        logger,
      );
      // The first load is the first piece in the lane. A scene map change
      // that arrives while it runs queues behind it; the drain waits for
      // both, so everything below starts from a registry that is complete.
      void registryLane.run("first load", (_position, signal) =>
        scenes.load({ signal }),
      );
      await registryLane.drain();
      await runStep("settings.start", () => settings.start(), logger);
      await runStep("state.start", () => state.start(), logger);
      await runStep("health.start", () => health.start(), logger);
      await runStep("scheduler.start", () => scheduler.start(), logger);
      await runStep("status.start", () => statusPublisher?.start(), logger);
      await runStep(
        "live.wire",
        () => {
          unwireLive = wireLiveChannel(live, apiDeps);
        },
        logger,
      );
      publishControllerIfChanged();
      controllerTicker = clock.every(
        publishControllerIfChanged,
        CONTROLLER_TICK_MS,
      );
      await runStep("config.watch", () => config.start(), logger);
      await runStep("scenes.watch", () => scenesWatcher.start(), logger);
      logger.info(`[pixdcon2] Running — UI on port ${listening}`);
      return { port: listening };
    },

    async stop() {
      if (stopping) return;
      stopping = true;
      logger.info("[pixdcon2] Stopping...");
      controllerTicker?.cancel();
      runtime.off("changed", onRuntimeChanged);
      unwireLive();
      await runStep("scenes.unwatch", () => scenesWatcher.stop(), logger);
      await runStep("config.stop", () => config.stop(), logger);
      await runStep("live.stop", () => live.stop(), logger);
      await server.stop();
      // No new scene work starts, and the piece that is running is told:
      // the lane's signal is aborted, so whatever it still awaits commits
      // nothing and is followed by nothing (see the header). The wait below
      // lets a short import end before the scenes are released; it is not
      // what keeps a long one from touching them.
      registryLane.close();
      const drainLimit = new AbortController();
      await Promise.race([
        registryLane.drain(),
        clock.sleep(REGISTRY_DRAIN_LIMIT_MS, drainLimit.signal),
      ]);
      drainLimit.abort(); // the limit's timer does not outlive the wait
      await runStep("scheduler.stop", () => scheduler.stop(), logger);
      await runStep("scenes.release", () => sceneRuntime.releaseAll(), logger);
      await runStep("health.stop", () => health.stop(), logger);
      await runStep("settings.stop", () => settings.stop(), logger);
      await runStep("state.stop", () => state.stop(), logger);
      await runStep("status.stop", () => statusPublisher?.stop(), logger);
      await runStep("runtime.stop", () => runtime.stop(), logger);
      await runStep("overlays.stop", () => overlays.stop(), logger);
      await runStep("ownership.stop", () => ownership.stop(), logger);
      await runStep("mqtt.stop", () => mqtt?.stop(), logger);
      logger.info("[pixdcon2] Stopped");
    },
  };
}

/** Run as the process entry point: signals, error handlers, exit codes. */
async function main() {
  /** @type {Awaited<ReturnType<typeof createApp>>|null} */
  let app = null;
  let exiting = false;

  /**
   * @param {string} reason
   * @param {number} code
   */
  const shutdown = async (reason, code) => {
    if (exiting) return;
    exiting = true;
    const watchdog = setTimeout(() => process.exit(code), SHUTDOWN_LIMIT_MS);
    watchdog.unref();
    try {
      app?.logger.info(`[pixdcon2] ${reason}`);
      await app?.stop();
    } catch (error) {
      console.error(
        `[pixdcon2] Shutdown failed: ${error instanceof Error ? error.message : String(error)}`,
      );
      code = 1;
    }
    process.exit(code);
  };

  process.on("SIGINT", () => void shutdown("SIGINT received", 0));
  process.on("SIGTERM", () => void shutdown("SIGTERM received", 0));
  process.on("uncaughtException", (error) => {
    console.error(`[pixdcon2] Uncaught exception: ${error?.stack ?? error}`);
    void shutdown("uncaught exception", 1);
  });
  process.on("unhandledRejection", (reason) => {
    console.error(
      `[pixdcon2] Unhandled rejection: ${reason instanceof Error ? reason.stack : String(reason)}`,
    );
    void shutdown("unhandled rejection", 1);
  });

  try {
    app = await createApp();
    await app.start();
  } catch (error) {
    console.error(
      `[pixdcon2] Fatal: ${error instanceof Error ? error.message : String(error)}`,
    );
    await shutdown("startup failure", 1);
  }
}

if (
  process.argv[1] &&
  fileURLToPath(import.meta.url) === resolve(process.argv[1])
) {
  await main();
}
